use anyhow::{anyhow, Context, Result};
use std::path::{Path, PathBuf};
use std::sync::OnceLock;

use super::archive::read_prefix;
use super::save_thumb;

/// Helper generated by `build.rs`: the Cineware GLB exporter embedded in the
/// application binary (empty stub on non-Windows builds).
mod embedded_helper {
    include!(concat!(env!("OUT_DIR"), "/c4d_preview_exe.rs"));
}

const C4D_PREVIEW_HELPER: &str = "c4d_preview.exe";

static C4D_HELPER_PATH: OnceLock<Option<PathBuf>> = OnceLock::new();

/// Cinema 4D previews sit in the IFF `FORM`/`MC4D` header block, usually as a
/// `THMB` chunk holding JPEG or PNG bytes. The header is the only part worth
/// reading, so the scan is bounded to the first 8 MB.
const C4D_HEADER_WINDOW: u64 = 8 * 1024 * 1024;

/// Resolve the Cineware GLB helper, in order:
///
/// 1. `POLYSTASH_C4D_PREVIEW` — absolute path override for development.
/// 2. `c4d_preview.exe` next to the running PolyStash executable.
/// 3. `<exe dir>/c4d_preview/c4d_preview.exe` — sidecar layout.
/// 4. The helper embedded at build time, extracted to
///    `%TEMP%\polystash_c4d\c4d_preview.exe` on first use.
fn helper_next_to_exe() -> Option<PathBuf> {
    let exe = std::env::current_exe().ok()?;
    let dir = exe.parent()?;
    [dir.join(C4D_PREVIEW_HELPER), dir.join("c4d_preview").join(C4D_PREVIEW_HELPER)]
        .into_iter()
        .find(|path| path.is_file())
}

fn extract_embedded_helper() -> Option<PathBuf> {
    let bytes = embedded_helper::C4D_PREVIEW_EXE?;
    let dir = std::env::temp_dir().join("polystash_c4d");
    let exe = dir.join(C4D_PREVIEW_HELPER);
    let up_to_date = std::fs::metadata(&exe)
        .map(|metadata| metadata.len() == bytes.len() as u64)
        .unwrap_or(false);
    if !up_to_date {
        std::fs::create_dir_all(&dir).ok()?;
        std::fs::write(&exe, bytes).ok()?;
    }
    Some(exe)
}

fn c4d_helper_path() -> Option<PathBuf> {
    C4D_HELPER_PATH
        .get_or_init(|| {
            if let Ok(override_path) = std::env::var("POLYSTASH_C4D_PREVIEW") {
                let candidate = PathBuf::from(override_path);
                if candidate.is_file() {
                    return Some(candidate);
                }
            }
            helper_next_to_exe().or_else(extract_embedded_helper)
        })
        .clone()
}

/// Run the Cineware helper to convert a `.c4d` scene into a self-contained GLB.
///
/// Returns an error when no helper is available, when the helper cannot read the
/// scene (for example a `.c4d` saved without polygon caches), or when it does
/// not produce an output file. The caller falls back to the embedded preview.
pub(crate) async fn export_c4d_glb(source: &Path, output: &Path) -> Result<()> {
    let helper = c4d_helper_path()
        .ok_or_else(|| anyhow!("c4d_preview helper is not available in this build"))?;
    let helper = helper.to_string_lossy().into_owned();

    if let Some(parent) = output.parent() {
        tokio::fs::create_dir_all(parent).await?;
    }

    let status = super::spawn_command(&helper)
        .arg(source)
        .arg(output)
        .status()
        .await
        .with_context(|| format!("failed to start {helper}"))?;

    if !status.success() {
        let _ = tokio::fs::remove_file(output).await;
        return Err(anyhow!("c4d_preview exited with status {status}"));
    }

    if !output.is_file() {
        return Err(anyhow!("c4d_preview produced no GLB"));
    }

    Ok(())
}

/// Blender stores a rendered preview near the start of the file as a plain PNG
/// chunk. Large scenes can push that chunk past 4 MB, so the scan covers 8 MB.
const BLEND_PREVIEW_WINDOW: u64 = 8 * 1024 * 1024;

/// Byte-scan for the embedded preview PNG. This is a heuristic, not a format
/// parser: no usable preview means the caller completes without a thumbnail
/// and the frontend renders the model live.
pub(crate) fn extract_preview_png_thumb(source: &Path, output: &Path) -> Result<()> {
    let head = read_prefix(source, BLEND_PREVIEW_WINDOW)?;
    let index = super::find_png(&head)
        .ok_or_else(|| anyhow!("No embedded preview image found"))?;
    let img = image::load_from_memory(&head[index..])?;
    save_thumb(&img, output)
}

/// Cinema 4D (`.c4d`) thumbnail extraction. The file is an IFF container whose
/// `MC4D`/`FORM` header carries a `THMB` preview chunk encoded as JPEG or PNG.
/// This is a best-effort byte scan of the header window, not a chunk parser: a
/// miss returns `Err` so the caller can complete without a thumbnail.
pub(crate) fn extract_c4d_thumb(source: &Path, output: &Path) -> Result<()> {
    let head = read_prefix(source, C4D_HEADER_WINDOW)?;

    if !has_c4d_container(&head) {
        tracing::warn!(
            "{} has no MC4D/FORM marker near the start; scanning for a preview anyway",
            source.display()
        );
    }

    let index = preview_signature(&head)
        .ok_or_else(|| anyhow!("No embedded C4D preview image found"))?;
    let img = image::load_from_memory(&head[index..])?;
    save_thumb(&img, output)
}

/// True when the container fourCC appears in the opening bytes of the file.
fn has_c4d_container(head: &[u8]) -> bool {
    let probe = head.get(..64).unwrap_or(head);
    probe.windows(4).any(|w| w == b"MC4D" || w == b"FORM")
}

/// Offset of the earliest preview signature: JPEG (`FF D8 FF`) start-of-image
/// or the PNG magic. JPEG wins ties only if it appears first.
fn preview_signature(bytes: &[u8]) -> Option<usize> {
    let jpeg = bytes.windows(3).position(|w| w == [0xFF, 0xD8, 0xFF]);
    let png = super::find_png(bytes);

    match (jpeg, png) {
        (Some(jpeg), Some(png)) => Some(jpeg.min(png)),
        (jpeg, png) => jpeg.or(png),
    }
}
